import tensorflow as tf
import numpy as np
import matplotlib.pyplot as plt
from tensorflow.keras import layers, models

# Synthetic dataset (1000 samples, 20 features, binary labels)
X = np.random.normal(0, 1, (1000, 20))
y = (X[:, 0] + X[:, 1] > 0).astype(int)
X_train, X_val = X[:800], X[800:]
y_train, y_val = y[:800], y[800:]

# Define model architectures (all use 'binary_crossentropy' loss and 'adam')
def build_tiny():
    return models.Sequential([layers.Dense(4, activation='relu', input_shape=(20,)), layers.Dense(1, activation='sigmoid')])

def build_small():
    return models.Sequential([layers.Dense(16, activation='relu', input_shape=(20,)), layers.Dense(1, activation='sigmoid')])

def build_medium():
    return models.Sequential([layers.Dense(64, activation='relu', input_shape=(20,)), layers.Dense(32, activation='relu'), layers.Dense(1, activation='sigmoid')])

def build_large():
    return models.Sequential([layers.Dense(128, activation='relu', input_shape=(20,)), layers.Dense(64, activation='relu'), layers.Dense(32, activation='relu'), layers.Dense(1, activation='sigmoid')])

